import os
import base64
import requests

def extract_invoice_fields(payload, config=None):
    config = config or {}
    api_key = config.get("api_key") or os.getenv("GOOGLE_CLOUD_API_KEY")
    if not api_key:
        raise ValueError("Google Cloud API key is required")

    # Encode the payload (assuming it's a file path or base64 string)
    if isinstance(payload, str) and os.path.exists(payload):
        with open(payload, "rb") as file:
            encoded_payload = base64.b64encode(file.read()).decode("utf-8")
    else:
        encoded_payload = payload  # assuming it's already base64 encoded

    # Google Cloud Document AI API endpoint and model
    endpoint = f"https://us-documentai.googleapis.com/v1/projects/{config.get('project_id', os.getenv('GOOGLE_CLOUD_PROJECT_ID'))}/locations/us/processors/pretrained-invoice-v1.2-2023-11-10:process"

    headers = {
        "Authorization": f"Bearer {api_key}",
        "Content-Type": "application/json"
    }

    request_body = {
        "rawDocument": {
            "content": encoded_payload,
            "mimeType": "application/pdf"
        }
    }

    response = requests.post(endpoint, headers=headers, json=request_body)
    response.raise_for_status()

    result = {
        "vendor": None,
        "date": None,
        "total": None,
        "line_items": []
    }

    document = response.json().get("document", {})
    entities = document.get("entities", [])

    for entity in entities:
        if entity.get("type") == "supplier_name":
            result["vendor"] = entity.get("mentionText")
        elif entity.get("type") == "transaction_date":
            result["date"] = entity.get("mentionText")
        elif entity.get("type") == "total_amount":
            result["total"] = entity.get("mentionText")
        elif entity.get("type") == "line_item":
            line_item = {
                "description": None,
                "quantity": None,
                "unit_price": None,
                "amount": None
            }
            for prop in entity.get("properties", []):
                if prop.get("type") == "line_item/description":
                    line_item["description"] = prop.get("mentionText")
                elif prop.get("type") == "line_item/quantity":
                    line_item["quantity"] = prop.get("mentionText")
                elif prop.get("type") == "line_item/unit_price":
                    line_item["unit_price"] = prop.get("mentionText")
                elif prop.get("type") == "line_item/amount":
                    line_item["amount"] = prop.get("mentionText")
            if any(line_item.values()):
                result["line_items"].append(line_item)

    return result
